import{_ as r,C as i,c as l,o as g,a3 as o,G as s,j as a,a as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Create a lead","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/acquire-leads/create-lead.md","filePath":"master/sales/crm/acquire-leads/create-lead.md","lastUpdated":1793789158000}'),d={name:"master/sales/crm/acquire-leads/create-lead.md"};function h(c,t,m,u,p,b){const e=i("ImagePopup");return g(),l("div",null,[t[0]||(t[0]=o('<h1 id="create-a-lead" tabindex="-1">Create a lead <a class="header-anchor" href="#create-a-lead" aria-label="Permalink to &quot;Create a lead&quot;">​</a></h1><p>A lead is the first record of a possible sale. It holds who contacted you, what they want and where they came from. You use leads to sort enquiries before you spend time on a full opportunity.</p><blockquote><p><strong>In simple words:</strong> A lead is a note about someone who might buy. You fill it in, check it, then convert it or close it as lost.</p></blockquote><p>Open the list with <code>CRM → Leads → Leads</code>. If you do not see <strong>Leads</strong>, switch on <strong>Lead Qualification</strong> first.</p><div class="info custom-block"><p class="custom-block-title">About the example</p><p>This page records one enquiry. Rajesh Sharma of <strong>Sharma Textiles Pvt. Ltd.</strong> asks for an ERP for his textile manufacturing unit. The same lead continues on the next pages.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><strong>Lead Qualification</strong> adds a qualification step before an opportunity exists. It turns on the <strong>Leads</strong> area.</p><ol><li>Go to <code>CRM → Settings → Manage CRM</code>.</li><li>Switch on <strong>Lead Qualification</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol>',8)),s(e,{src:"/images1/crm/settings-lead-qualification.png",alt:"Manage CRM settings page with Lead Qualification switched on"}),t[1]||(t[1]=a("p",null,[n("See "),a("a",{href:"./../configuration/settings.html"},"CRM settings"),n(".")],-1)),t[2]||(t[2]=a("h2",{id:"the-leads-list",tabindex:"-1"},[n("The leads list "),a("a",{class:"header-anchor",href:"#the-leads-list","aria-label":'Permalink to "The leads list"'},"​")],-1)),t[3]||(t[3]=a("p",null,"The list shows every lead, newest first.",-1)),s(e,{src:"/images1/crm/leads-list.png",alt:"Leads list with view tabs, Import, Export, New Lead, Group by and the layout switcher"}),t[4]||(t[4]=o('<h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs above the list are ready-made views:</p><ul><li><strong><em>Default:</em></strong> All leads.</li><li><strong><em>My Leads:</em></strong> Leads where you are the salesperson.</li><li><strong><em>Unassigned:</em></strong> Leads that have no salesperson yet.</li><li><strong><em>All Leads:</em></strong> Every open lead.</li><li><strong><em>Lost:</em></strong> Leads that you closed as lost or deleted. Open one to see the <strong>Lost Reason</strong> and <strong>Closing Note</strong>.</li></ul><p>A switcher in the toolbar changes the layout. Choose <strong>List</strong>, <strong>Kanban</strong> or <strong>Graph</strong>. Kanban and Graph work on the field you pick in <strong>Group by</strong>. The Graph without a grouping counts leads by month.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The list shows <strong>Lead</strong>, <strong>Email</strong>, <strong>City</strong>, <strong>Country</strong>, <strong>Salesperson</strong> and <strong>Sales Team</strong>.</p><p>Use the column toggle to show more: <strong>Contact Name</strong>, <strong>Company Name</strong>, <strong>Phone</strong>, <strong>Priority</strong>, <strong>Tags</strong>, <strong>Source</strong>, <strong>Medium</strong>, <strong>Lost Reason</strong> and <strong>Created On</strong>.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li>Type in the search box to find a lead by <strong>Lead</strong>, <strong>Contact Name</strong>, <strong>Company Name</strong> or <strong>Email</strong>.</li><li>Use the filter icon to build rules on fields such as <strong>Lead</strong>, <strong>Contact Name</strong>, <strong>Company Name</strong>, <strong>Email</strong>, <strong>Phone</strong>, <strong>City</strong>, <strong>Country</strong>, <strong>Stage</strong>, <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Tags</strong>, <strong>Priority</strong>, <strong>Source</strong>, <strong>Medium</strong>, <strong>Campaign</strong>, <strong>Probability</strong> and <strong>Created On</strong>.</li><li>Use <strong>Group by</strong> to fold the list by <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Source</strong> or <strong>Priority</strong>.</li><li>Click <strong>Export</strong> to download leads. Click <strong>Import</strong> to load leads from a file.</li><li>Tick several rows to use the bulk actions. See <a href="#bulk-actions">Bulk actions</a>.</li></ul><p>See <a href="./../../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><h2 id="create-a-lead-1" tabindex="-1">Create a lead <a class="header-anchor" href="#create-a-lead-1" aria-label="Permalink to &quot;Create a lead&quot;">​</a></h2><ol><li>Go to <code>CRM → Leads → Leads</code>.</li><li>Click <strong>New Lead</strong>.</li><li>Fill in the <strong>Lead</strong> section on the left and the <strong>Sales</strong>, <strong>Marketing</strong> and <strong>Analysis</strong> sections on the right.</li><li>Click <strong>Create</strong>. Use <strong>Create &amp; create another</strong> to save and open an empty form.</li></ol>',12)),s(e,{src:"/images1/crm/create-lead-form.png",alt:"New Lead form filled in for Sharma Textiles"}),t[5]||(t[5]=o('<p>After you save, Aureus shows the lead page and the message <strong>Lead created</strong>. A new lead gets the first stage of your pipeline and you as salesperson, unless you choose otherwise.</p><h3 id="lead" tabindex="-1">Lead <a class="header-anchor" href="#lead" aria-label="Permalink to &quot;Lead&quot;">​</a></h3><ul><li><strong><em>Lead name:</em></strong> A short title for the enquiry. Required, up to 255 characters. The hint reads <strong>e.g. Product Pricing</strong>.</li><li><strong><em>Probability:</em></strong> Your estimate of the chance to win, from 0 to 99.99 %. Leave it empty to let Aureus work it out. The field then shows <strong>Automatic</strong>. See <a href="./../assign-and-track/lead-scoring.html">Lead scoring</a>.</li><li><strong><em>Company Name:</em></strong> The company that contacted you.</li><li><strong><em>Address:</em></strong> Fill in <strong>Street...</strong>, <strong>Street 2...</strong>, <strong>City</strong>, <strong>ZIP</strong>, <strong>State</strong> and <strong>Country</strong>. Pick the <strong>Country</strong> first, because the <strong>State</strong> list shows only states of that country.</li><li><strong><em>Website:</em></strong> The company web address. It must be a valid URL such as <code>https://www.example.com</code>.</li><li><strong><em>Contact Name:</em></strong> The person you will talk to.</li><li><strong><em>Email:</em></strong> Their email address. It must be a valid address.</li><li><strong><em>Job Position:</em></strong> Their role in the company.</li><li><strong><em>Phone:</em></strong> Their phone number.</li></ul><p><strong>Example:</strong> Enter <code>ERP implementation for textile manufacturing unit</code> as <strong>Lead name</strong>. Set <strong>Company Name</strong> to <code>Sharma Textiles Pvt. Ltd.</code> and <strong>Contact Name</strong> to <code>Rajesh Sharma</code>. Use <code>rajesh.sharma@sharmatextiles.in</code> and <code>+91 98250 41263</code>. Enter <strong>Job Position</strong> <code>Managing Director</code>, <strong>City</strong> <code>Surat</code>, and <strong>Country</strong> <code>India</code>.</p><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li><strong><em>Notes:</em></strong> Free text with formatting. Write what you learned, such as the size of the unit or what the contact asked for.</li></ul><p><strong>Example:</strong> <code>Rajesh runs a 220-employee weaving and dyeing unit. Inventory and payroll are tracked in Excel today. Wants a demo and pricing for 40 users.</code></p><h3 id="sales" tabindex="-1">Sales <a class="header-anchor" href="#sales" aria-label="Permalink to &quot;Sales&quot;">​</a></h3><ul><li><strong><em>Salesperson:</em></strong> The user who owns the lead. It starts as you. Only active users of the lead company are listed.</li><li><strong><em>Sales Team:</em></strong> The team that handles the lead. Only teams of the lead company are listed.</li><li><strong><em>Priority:</em></strong> <strong>Low</strong>, <strong>Medium</strong>, <strong>High</strong> or <strong>Very High</strong>. It starts as <strong>Low</strong>.</li><li><strong><em>Tags:</em></strong> Labels that group leads, such as <strong>Software</strong> or <strong>Consulting</strong>. You can pick many. Type a new name and create it on the spot. See <a href="./../configuration/tags.html">Tags</a>.</li></ul><p><strong>Example:</strong> Keep yourself as <strong>Salesperson</strong>. Set <strong>Priority</strong> to <strong>High</strong> and add the tag <strong>Software</strong>.</p><h3 id="marketing" tabindex="-1">Marketing <a class="header-anchor" href="#marketing" aria-label="Permalink to &quot;Marketing&quot;">​</a></h3><ul><li><strong><em>Company:</em></strong> Your own company that owns the lead. It starts as the company you work in. Change it only if you run several companies.</li><li><strong><em>Campaign:</em></strong> The marketing campaign that brought the lead.</li><li><strong><em>Medium:</em></strong> The channel, such as <strong>Email</strong>.</li><li><strong><em>Source:</em></strong> Where the lead came from, such as <strong>Newsletter</strong>.</li><li><strong><em>Referred By:</em></strong> The name of the person who sent the lead to you.</li></ul><p><strong>Example:</strong> Choose the campaign <strong>Email Campaign - Products</strong>, the medium <strong>Email</strong> and the source <strong>Newsletter</strong>. Type <code>Mehul Patel</code> in <strong>Referred By</strong>.</p><h3 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h3><ul><li><strong><em>Assignment Date:</em></strong> The date and time the lead got its salesperson. Aureus fills it. You cannot type here.</li><li><strong><em>Closed Date:</em></strong> The date and time the lead was closed. It stays empty until the lead is closed.</li></ul><h3 id="probability-details" tabindex="-1">Probability details <a class="header-anchor" href="#probability-details" aria-label="Permalink to &quot;Probability details&quot;">​</a></h3><p>Next to <strong>Probability</strong>, an information icon opens <strong>Probability details</strong>. It shows the <strong>Computed probability</strong> and the <strong>Sales team</strong> used. If you typed the probability by hand, the window says so.</p><p>If you typed your own value, a refresh icon appears. Click <strong>Use computed probability</strong> to go back to the automatic value.</p><h2 id="the-lead-page" tabindex="-1">The lead page <a class="header-anchor" href="#the-lead-page" aria-label="Permalink to &quot;The lead page&quot;">​</a></h2><p>After you save, the lead opens in read mode. A switcher at the top has these tabs:</p><ul><li><strong><em>View:</em></strong> The details in read mode.</li><li><strong><em>Edit:</em></strong> The same form, ready to change. Saving shows <strong>Lead updated</strong>.</li><li><strong><em>Activities:</em></strong> Planned and done follow-ups for this lead. Click <strong>Schedule Activity</strong> to add one. See <a href="./../pipeline/schedule-activities.html">Schedule activities</a>.</li><li><strong><em>Similar Leads:</em></strong> Other leads and opportunities that share the same email, phone number or customer. This tab appears only when Aureus finds at least one, and a number on the tab shows how many.</li></ul>',21)),s(e,{src:"/images1/crm/lead-view.png",alt:"Lead page in View mode with the header buttons and the View, Edit and Activities tabs"}),t[6]||(t[6]=o('<p>Open <strong>Chatter</strong> in the header to write notes, send messages and log activities on the lead. See <a href="./../../../getting-started/chatter/introduction.html">Chatter</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>A lead is either open or lost. The buttons in the header change what happens to it.</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Chatter</strong></td><td>Opens the message and note panel for the lead.</td></tr><tr><td><strong>Convert to Opportunity</strong></td><td>Turns the lead into an opportunity. See <a href="./convert-lead.html">Convert a lead</a>.</td></tr><tr><td><strong>Lost</strong></td><td>Opens <strong>Mark as lost</strong>. Choose a <strong>Lost Reason</strong>, add a <strong>Closing Note</strong> and click <strong>Mark as Lost</strong>.</td></tr><tr><td><strong>Send email</strong></td><td>Opens a window with <strong>To</strong>, <strong>Subject</strong> and <strong>Message</strong>. It shows only when the lead has an email.</td></tr><tr><td><strong>Send SMS</strong></td><td>Opens a window with <strong>Recipient</strong> and <strong>Message</strong>. Use the international format for the number.</td></tr><tr><td><strong>Delete</strong></td><td>Removes the lead from the open views. It then appears under <strong>Lost</strong>.</td></tr><tr><td><strong>Restore</strong></td><td>Shows only on a lost or deleted lead. It brings the lead back to the open views.</td></tr></tbody></table><p>On the <strong>Edit</strong> tab you see <strong>Chatter</strong>, <strong>Convert to Opportunity</strong> and <strong>Lost</strong>.</p>',5)),s(e,{src:"/images1/crm/lead-mark-lost-dialog.png",alt:"Mark as lost window with the Lost Reason Too expensive and a Closing Note"}),t[7]||(t[7]=o('<h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><p>In the list, each row has a clock icon to <strong>Schedule Activity</strong>. The row menu holds <strong>View</strong>, <strong>Edit</strong>, <strong>Convert to Opportunity</strong>, <strong>Send email</strong>, <strong>Send SMS</strong>, <strong>Lost</strong>, <strong>Restore</strong> and <strong>Force delete</strong>. <strong>Force delete</strong> removes the lead for good.</p><h3 id="bulk-actions" tabindex="-1">Bulk actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk actions&quot;">​</a></h3><p>Tick several rows to see these actions:</p><ul><li><strong>Export</strong>, <strong>Restore</strong>, <strong>Delete</strong> and <strong>Force delete</strong>.</li><li><strong>Mark Lost</strong> closes all ticked leads with one <strong>Lost Reason</strong> and <strong>Closing Note</strong>.</li><li><strong>Convert to Opportunities</strong> converts many leads at once. See <a href="./convert-lead.html">Convert a lead</a>.</li><li><strong>Merge</strong> joins duplicate leads into one. See <a href="./convert-lead.html">Convert a lead</a>.</li><li>Email and SMS actions send one message to all ticked leads. Leads without an email or valid number are skipped.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li><strong>Lost</strong> sets the probability to 0, stores the closing date, and moves the lead to the <strong>Lost</strong> view. Nothing is erased.</li><li><strong>Restore</strong> clears the lost reason and the closing note, and the probability becomes automatic again.</li><li>The email address and the phone number are cleaned and stored for matching. Two records with the same email, or the same phone number, show up as similar leads.</li><li>When <strong>Automatic Lead Assignment</strong> is on and set to <strong>Repeatedly</strong>, a new lead with no team or salesperson is given to a team and a member straight away. See <a href="./../assign-and-track/">Assign and track</a>.</li><li>Saving a lead recalculates its automatic probability.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Fill in the email and phone. They help Aureus find similar leads and let you reach the contact.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A lead with a probability of 100 % cannot be converted. Lower the probability first.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./convert-lead.html">Convert a lead</a></li><li><a href="./lead-generation.html">Generate leads from visitors</a></li><li><a href="./../assign-and-track/lead-scoring.html">Lead scoring</a></li><li><a href="./../configuration/lost-reasons.html">Lost reasons</a></li><li><a href="./../configuration/tags.html">Tags</a></li></ul>',11))])}const w=r(d,[["render",h]]);export{f as __pageData,w as default};
